/* Functional client. Private actions use a real server session, never local passwords. */
(async function(){
'use strict';
const roots=[...document.querySelectorAll('.platform-view,[data-view="popular"]')].filter(el=>el.dataset.view);
const C=window.DGCore,key='dg-platform-v1';let data,ingredients,state,user=null,ratings={},server=false,serverFeatures={},notice='';
const apiBase=window.DG_CONFIG?.apiBase;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=n=>Number(n.toFixed(1)).toLocaleString('ru-RU');
const recipe=id=>data.recipes.find(r=>r.id===id);
const builtIn=new Set(['negroni','margarita','cranberry','cosmopolitan','mojito','virgin-mojito','lemonade','berry-spritz']);
const recipeURL=id=>builtIn.has(id)?'recipe-'+id+'.html':'recipe.html?id='+encodeURIComponent(id);
let filters={},mode=new URLSearchParams(location.search).get('mode')||'create',selectedSubs={},recipePortions=1,pendingShared=null;
async function api(path,method='GET',body){if(!apiBase)throw Error('Сервер аккаунтов не подключён к этой версии сайта.');const res=await fetch(apiBase+path,{method,credentials:'same-origin',headers:{'X-Requested-With':'DrunkenGuide',...(body!==undefined?{'Content-Type':'application/json'}:{})},body:body===undefined?undefined:JSON.stringify(body)});let result;try{result=await res.json()}catch{throw Error('Сервер вернул непонятный ответ. Попробуйте позже.')}if(!res.ok)throw Error(result.error||'Не удалось выполнить действие.');return result}
function load(){let raw={};try{raw=JSON.parse(localStorage.getItem(key)||'{}');if(!raw||typeof raw!=='object')raw={};if(!Object.hasOwn(raw,'favorites'))raw.favorites=JSON.parse(localStorage.getItem('drunken-favorites')||'[]')}catch{}return C.validState(raw,data)}
function persist(){try{localStorage.setItem(key,JSON.stringify(state));localStorage.setItem('drunken-favorites',JSON.stringify(state.favorites));return true}catch{setNotice('Хранилище браузера недоступно или заполнено. Изменение не сохранено.');return false}}
function setNotice(message){notice=message;document.querySelectorAll('.platform-message').forEach(el=>el.textContent=message)}
function options(items,value='',first='Любое'){return '<option value="">'+esc(first)+'</option>'+items.map(item=>{const id=typeof item==='string'?item:item.id,name=typeof item==='string'?item:item.name;return `<option value="${esc(id)}"${id===value?' selected':''}>${esc(name)}</option>`}).join('')}
const recipePhotos={"negroni": "qgdu971561574065", "margarita": "5noda61589575158", "cosmopolitan": "kpsajh1504368362", "mojito": "metwgh1606770327"};
function photo(r){if(r.photo&&apiBase&&/^[a-f0-9]{32}$/.test(r.photo))return `<img class="page-photo" src="${apiBase}/media/${r.photo}" alt="${esc(r.name)}" loading="lazy">`;if(recipePhotos[r.id])return `<img class="page-photo real-recipe-photo" src="https://www.thecocktaildb.com/images/media/drink/${recipePhotos[r.id]}.jpg" alt="${esc(r.name)}" loading="lazy">`;const mockIndex={'virgin-mojito':0,'lemonade':1,'berry-spritz':2}[r.id];if(Number.isInteger(mockIndex)){const x=mockIndex*512+6;return `<svg class="page-photo" viewBox="${x} 5 500 1000" preserveAspectRatio="xMidYMid meet" aria-hidden="true"><defs><clipPath id="mock-photo-${esc(r.id)}"><rect x="${x}" y="5" width="500" height="1000"/></clipPath></defs><image href="assets/mocktail-photos.png" width="1536" height="1024" clip-path="url(#mock-photo-${esc(r.id)})"/></svg>`}if(!r.tile)return '<div class="photo-placeholder"><span>Фотография пока не добавлена</span></div>';const [x,y]=r.tile,id='p-'+esc(r.id);return `<svg class="page-photo" viewBox="${x+5} ${y+5} 374 480" preserveAspectRatio="xMidYMid meet" aria-hidden="true"><defs><clipPath id="${id}"><rect x="${x+5}" y="${y+5}" width="374" height="480"/></clipPath></defs><image href="assets/drink-collection.png" width="1536" height="1024" clip-path="url(#${id})"/></svg>`}
function card(r){const rating=ratings[r.id];return `<article class="drink-card"><a class="drink-card-photo" href="${recipeURL(r.id)}" aria-label="Открыть ${esc(r.name)}">${photo(r)}</a><div class="drink-card-body"><p class="drink-meta">${esc(r.base)} · ${esc(r.taste)}</p><h3><a href="${recipeURL(r.id)}">${esc(r.name)}</a></h3><p>${esc(r.intro)}</p><p class="real-rating">${rating?.count?`★ ${number(rating.average)} · оценок: ${rating.count}`:'Пока без оценок'} · ≈ ${number(C.abv(r,ingredients))}%</p><div class="card-tool-row"><button class="tool-button" data-action="favorite" data-id="${r.id}" aria-pressed="${state.favorites.includes(r.id)}">${state.favorites.includes(r.id)?'♥ Сохранено':'♡ Избранное'}</button><button class="tool-button" data-action="compare" data-id="${r.id}" aria-pressed="${state.compare.includes(r.id)}">${state.compare.includes(r.id)?'✓ В сравнении':'⚖ Сравнить'}</button></div><div class="drink-card-actions"><a href="${recipeURL(r.id)}">Открыть рецепт →</a><button class="tool-button" data-action="party-add" data-id="${r.id}">+ В план</button></div></div></article>`}
function grid(list){return list.length?'<div class="drink-grid">'+list.map(card).join('')+'</div>':'<div class="empty-state"><h2>Ничего не найдено</h2><p>Измените фильтры или откройте <a class="text-link" href="catalog.html">весь каталог</a>.</p></div>'}
function toolbar(){return '<p class="platform-message" role="status" aria-live="polite">'+esc(notice)+'</p>'}
function unique(field,list=data.recipes){return [...new Set(list.map(r=>r[field]))]}
function filterFields(occasion=false){const fields=[['base','Основа',unique('base')],['taste','Вкус',unique('taste')],['strength','Крепость',['Без алкоголя','Лёгкий','Средний','Крепкий']],['complexity','Сложность',unique('complexity')],['color','Цвет',unique('color')],['method','Способ',unique('method')],['type','Тип',unique('type')],['ingredient','Ингредиент',data.ingredients.filter(i=>i.id!=='ice')]];return `<form class="advanced-filters"><label class="wide-filter">Название или ингредиент<input type="search" data-filter="query" value="${esc(filters.query||'')}" placeholder="Например, ром или мята"></label>${occasion?`<label>Повод<select data-filter="occasion">${options(data.occasions,filters.occasion)}</select></label><label>Гостей<input type="number" min="1" max="100" value="1" id="guest-count"></label>`:''}${fields.map(([k,title,items])=>`<label>${title}<select data-filter="${k}">${options(items,filters[k])}</select></label>`).join('')}<label>Не дольше<select data-filter="minutes">${options([{id:'5',name:'5 минут'},{id:'10',name:'10 минут'},{id:'20',name:'20 минут'}],filters.minutes)}</select></label><label class="checkbox-label"><input type="checkbox" data-filter="available"${filters.available?' checked':''}> Всё есть дома</label><button type="button" class="text-link reset-button" data-action="reset-filters">Сбросить фильтры</button></form><p class="hint">Крепость расчётная, до разбавления льдом. Наличие ингредиентов берётся из <a href="builder.html?mode=bar">домашнего бара</a>.</p>`}
function catalogResults(root,view){let list=data.recipes.filter(r=>view==='mocktails'?!r.alcoholic:['occasions','builder'].includes(view)?true:r.alcoholic);list=list.filter(r=>C.matches(r,filters,ingredients,state.pantry));root.querySelector('.catalog-results').innerHTML=`<p class="result-count" role="status">Найдено: ${list.length}</p>`+grid(list)}
function renderCatalog(root,view){if(view==='occasions')filters.occasion=filters.occasion||'';root.innerHTML=toolbar()+(view==='occasions'?'<div class="occasion-pills">'+data.occasions.map(o=>`<button class="tool-button" data-action="occasion" data-id="${o.id}">${esc(o.name)}</button>`).join('')+'</div>':'')+filterFields(view==='occasions')+'<div class="catalog-results"></div>';catalogResults(root,view);root.querySelector('form').addEventListener('submit',e=>e.preventDefault())}
function comparePage(root){const list=state.compare.map(recipe).filter(Boolean);if(!list.length){root.innerHTML=toolbar()+'<div class="empty-state"><h2>Выберите коктейли для сравнения</h2><p>В каталоге можно выбрать до четырёх рецептов.</p><a class="outline-button" href="catalog.html">Открыть каталог</a></div>';return}const rows=[['Основа',r=>r.base],['Вкус',r=>r.taste],['Сложность',r=>r.complexity],['Крепость ≈',r=>number(C.abv(r,ingredients))+'%'],['Время',r=>r.minutes+' мин'],['Способ',r=>r.method],['Ингредиенты',r=>r.parts.map(p=>ingredients[p.id]?.name).join(', ')]];const counts={};list.forEach(r=>new Set(r.parts.map(p=>p.id)).forEach(id=>counts[id]=(counts[id]||0)+1));root.innerHTML=toolbar()+`<div class="comparison-scroll" tabindex="0" aria-label="Таблица сравнения — можно прокручивать"><table class="compare-table"><thead><tr><th scope="col">Характеристика</th>${list.map(r=>`<th scope="col"><a href="${recipeURL(r.id)}">${esc(r.name)}</a><button class="text-link" data-action="compare" data-id="${r.id}">Убрать</button></th>`).join('')}</tr></thead><tbody>${rows.map(([name,get])=>`<tr><th scope="row">${name}</th>${list.map(r=>`<td>${esc(get(r))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="glass-panel"><h2>Ингредиенты в сравнении</h2><h3>Повторяются</h3><p>${esc(Object.keys(counts).filter(id=>counts[id]>1).map(id=>ingredients[id].name).join(', ')||'Общих ингредиентов нет.')}</p>${list.map(r=>`<h3>Только в ${esc(r.name)}</h3><p>${esc(r.parts.filter(p=>counts[p.id]===1).map(p=>ingredients[p.id].name).join(', ')||'Уникальных ингредиентов нет.')}</p>`).join('')}<p class="hint">${esc(data.abvNote)}</p><button class="outline-button" data-action="compare-to-party">Добавить выбранные в план</button> <a class="text-link" href="planner.html">Открыть план →</a></div>`}
function planner(root){const list=Object.entries(state.party).map(([id,count])=>({r:recipe(id),count})).filter(x=>x.r);const totals=C.shopping(state.party,data.recipes,ingredients,state.pantry);root.innerHTML=toolbar()+(pendingShared?`<div class="glass-panel"><h2>План из ссылки</h2><p>${Object.entries(pendingShared).map(([id,n])=>esc(recipe(id)?.name||id)+' — '+n+' порций').join('<br>')}</p><p>Открытие заменит текущий план на этом устройстве. Сохранённые планы останутся.</p><button class="outline-button" data-action="shared-accept">Открыть этот план</button></div>`:'')+`<div class="glass-panel"><h2>Ваши коктейли</h2><label>Добавить рецепт<select id="party-recipe">${options(data.recipes)}</select></label><button class="outline-button" data-action="party-selected">Добавить в план</button>${list.length?list.map(({r,count})=>`<div class="party-row"><a href="${recipeURL(r.id)}">${esc(r.name)}</a><label>Порций<input type="number" min="1" max="100" data-party="${r.id}" value="${count}"></label><button class="tool-button" data-action="party-remove" data-id="${r.id}">Убрать</button></div>`).join(''):'<p>Добавьте коктейли из каталога или сравнения.</p>'}</div><div class="glass-panel"><h2>Список покупок</h2><p class="hint">Общие ингредиенты сложены. В столбце «Уже есть» укажите количество дома; его вычтем из потребности. Украшения проверяйте отдельно на странице рецепта.</p>${totals.length?`<div class="shopping-scroll"><table class="shopping-table"><thead><tr><th>Ингредиент</th><th>Всего</th><th>Уже есть</th><th>Купить</th><th>Готово</th></tr></thead><tbody>${totals.map(item=>{const amount=state.adjustments[item.id]??item.missing;return `<tr class="${state.bought[item.id]?'purchased':''}"><th scope="row">${esc(item.name)}</th><td>${number(item.total)} ${esc(item.unit)}</td><td><input aria-label="Уже есть: ${esc(item.name)}" type="number" min="0" max="100000" data-pantry="${item.id}" value="${state.pantry[item.id]||0}"></td><td><input aria-label="Купить: ${esc(item.name)}" type="number" min="0" max="100000" data-adjustment="${item.id}" value="${amount}"> ${esc(item.unit)}</td><td><input type="checkbox" data-bought="${item.id}" aria-label="Куплено: ${esc(item.name)}"${state.bought[item.id]?' checked':''}></td></tr>`}).join('')}</tbody></table></div><button class="tool-button" data-action="shopping-reset">Пересчитать ручные правки</button><button class="tool-button" data-action="copy-shopping">Скопировать список</button><button class="tool-button" data-action="share-party">Поделиться планом</button><p class="share-result" role="status"></p>`:'<p>После выбора рецептов здесь появится список.</p>'}</div><div class="glass-panel"><h2>Сохранённые планы и списки</h2><form id="save-plan"><label>Название<input name="name" maxlength="100" required placeholder="Например, субботний вечер"></label><button class="outline-button">Сохранить на устройстве</button></form>${state.plans.map((p,i)=>`<div class="saved-plan"><span>${esc(p.name)}</span><button class="tool-button" data-action="plan-load" data-id="${i}">Открыть</button><button class="tool-button" data-action="plan-delete" data-id="${i}">Удалить</button></div>`).join('')}<p class="hint">${user?'Чтобы сохранить планы в аккаунте, нажмите «Сохранить данные в аккаунте» в личном кабинете.':'Работает без регистрации. Для хранения на сервере потребуется вход в подключённой серверной версии.'}</p></div>`;root.querySelector('#save-plan').addEventListener('submit',e=>{e.preventDefault();if(!list.length){setNotice('Сначала добавьте хотя бы один коктейль.');return}if(state.plans.length>=20){setNotice('Можно хранить 20 планов. Удалите ненужный.');return}const name=new FormData(e.target).get('name').trim();if(!name){setNotice('Введите название плана.');return}state.plans.push({name,party:{...state.party},pantry:{...state.pantry},adjustments:{...state.adjustments},bought:{...state.bought}});persist();planner(root)})}
function builder(root){root.innerHTML=toolbar()+`<div class="builder-modes"><a class="outline-button${mode==='create'?' selected':''}" href="builder.html?mode=create">Свой рецепт</a><a class="outline-button${mode==='preferences'?' selected':''}" href="builder.html?mode=preferences">По предпочтениям</a><a class="outline-button${mode==='bar'?' selected':''}" href="builder.html?mode=bar">Что есть дома?</a></div>`;if(mode==='preferences'){root.innerHTML+=filterFields()+'<div class="catalog-results"></div>';catalogResults(root,'builder');root.querySelector('form').addEventListener('submit',e=>e.preventDefault());return}if(mode==='bar'){root.innerHTML+=`<div class="glass-panel"><h2>Мой домашний бар</h2><p>Укажите доступное количество. Рецепты рассчитаны на одну порцию; лёд не влияет на группу доступности.</p><div class="pantry-grid">${data.ingredients.map(i=>`<label>${esc(i.name)} (${esc(i.unit)})<input type="number" min="0" max="100000" data-pantry="${i.id}" value="${state.pantry[i.id]||0}"></label>`).join('')}</div></div><div class="bar-results"></div>`;barResults(root);return}root.innerHTML+=`<form id="custom-recipe" class="glass-panel"><h2>Создайте своё сочетание</h2><label>Название<input name="name" maxlength="100" required></label><label>Описание и инструкция приготовления<textarea name="description" maxlength="2000" required></textarea></label><label>Способ<select name="method"><option>Сборка в бокале</option><option>Смешивание</option><option>Шейкер</option></select></label><div class="custom-parts"></div><button class="tool-button" type="button" data-action="custom-add">+ Ингредиент</button><p class="custom-calculation" role="status"></p><p class="hint">${esc(data.abvNote)}</p><button class="outline-button">Сохранить рецепт на устройстве</button></form><div class="glass-panel"><h2>Мои рецепты</h2><div class="custom-saved">${customList()}</div></div>`;addCustomPart(root);addCustomPart(root);const preset=new URLSearchParams(location.search).get('ingredients');if(preset){const ids=[...new Set(preset.split(','))].filter(id=>ingredients[id]).slice(0,7);root.querySelector('.custom-parts').textContent='';ids.forEach(id=>{addCustomPart(root);const last=root.querySelector('.custom-part:last-child');last.querySelector('select').value=id;last.querySelector('input').value=ingredients[id].unit==='мл'?30:ingredients[id].unit==='г'?2:1});customCalculation(root)}root.querySelector('#custom-recipe').addEventListener('submit',e=>{e.preventDefault();const form=e.target;const parts=readCustom(root);if(!parts.length||!parts.some(p=>ingredients[p.id].unit==='мл')){setNotice('Добавьте хотя бы один жидкий ингредиент.');return}if(state.custom.length>=50){setNotice('Можно сохранить 50 своих рецептов.');return}const f=new FormData(form);if(!f.get('name').trim()||!f.get('description').trim()){setNotice('Введите название и описание.');return}state.custom.push({name:f.get('name').trim(),description:f.get('description').trim(),method:f.get('method'),parts});persist();form.reset();root.querySelector('.custom-saved').innerHTML=customList();setNotice('Ваш рецепт сохранён на этом устройстве.');customCalculation(root)})}
function customList(){return state.custom.length?state.custom.map((r,i)=>`<article class="custom-recipe-card"><h3>${esc(r.name)}</h3><p>${esc(r.description)}</p><p>${esc(r.method)} · ${number(C.volume(r,ingredients))} мл · ≈ ${number(C.abv(r,ingredients))}%</p><ul>${r.parts.map(p=>`<li>${esc(ingredients[p.id].name)} — ${number(p.amount)} ${esc(ingredients[p.id].unit)}</li>`).join('')}</ul>${server&&user?`<button class="tool-button" data-action="custom-submit" data-id="${i}">Предложить сообществу</button>`:""}<button class="tool-button" data-action="custom-delete" data-id="${i}">Удалить</button></article>`).join(''):'<p>Ваши рецепты появятся здесь.</p>'}
function addCustomPart(root){const div=document.createElement('div');div.className='custom-part';div.innerHTML=`<label>Ингредиент<select class="custom-ingredient">${options(data.ingredients,'','Выберите ингредиент')}</select></label><label>Количество<input class="custom-amount" type="number" min="0.1" max="10000" step="0.1" required value="30"></label><span class="custom-unit">мл / г</span><button type="button" class="tool-button" data-action="custom-remove">Убрать</button>`;root.querySelector('.custom-parts').append(div);customCalculation(root)}
function readCustom(root){return [...root.querySelectorAll('.custom-part')].map(el=>({id:el.querySelector('select').value,amount:Number(el.querySelector('input').value)})).filter(p=>ingredients[p.id]&&p.amount>0&&p.amount<=10000)}
function customCalculation(root){const r={parts:readCustom(root)};root.querySelector('.custom-calculation').textContent=`Объём жидкости: ${number(C.volume(r,ingredients))} мл · примерная крепость: ${number(C.abv(r,ingredients))}%`;root.querySelectorAll('.custom-part').forEach(el=>{el.querySelector('.custom-unit').textContent=ingredients[el.querySelector('select').value]?.unit||'мл / г'})}
function barResults(root){const groups=[[],[],[]];data.recipes.forEach(r=>groups[C.availability(r,state.pantry).group].push(r));root.querySelector('.bar-results').innerHTML=groups.map((list,i)=>`<section class="bar-group"><h2>${['Можно приготовить сейчас','Не хватает одного ингредиента','Нужно докупить несколько'][i]}</h2>${list.map(r=>{const missing=C.availability(r,state.pantry).missing;return `<article class="bar-result"><h3><a href="${recipeURL(r.id)}">${esc(r.name)}</a></h3><p>${missing.length?'Не хватает: '+esc(missing.map(p=>ingredients[p.id].name).join(', ')):'Все основные ингредиенты есть.'}</p><button class="tool-button" data-action="party-add" data-id="${r.id}">Добавить в план и список покупок</button></article>`}).join('')||'<p class="hint">Пока нет рецептов в этой группе.</p>'}</section>`).join('')}
function currentRecipe(root){let r=recipe(root.dataset.recipeId);for(const [from,to] of Object.entries(selectedSubs))r=C.substitute(r,from,to);return r}
function recipePage(root){const r=currentRecipe(root);if(!r){root.textContent='Рецепт не найден.';return}root.innerHTML=toolbar()+`<div class="recipe-layout"><div class="recipe-image">${photo(r)}<p class="photo-note">${esc(r.photo&&apiBase?r.photoLabel:recipePhotos[r.id]?'Фотография: TheCocktailDB':r.photoLabel)}</p></div><div class="recipe-summary"><p class="eyebrow">${esc(r.base)} · ${esc(r.taste)}</p><h2 class="recipe-title">${esc(r.name)}</h2><p class="page-intro">${esc(r.intro)}</p><div class="recipe-facts"><span>≈ <span class="recipe-abv">${number(C.abv(r,ingredients))}</span>%</span><span>${r.minutes} мин</span><span>${esc(r.complexity)}</span></div><div class="recipe-tools"><button class="outline-button" data-action="favorite" data-id="${r.id}" aria-pressed="${state.favorites.includes(r.id)}">${state.favorites.includes(r.id)?'♥ Сохранено':'♡ В избранное'}</button><button class="outline-button" data-action="compare" data-id="${r.id}">⚖ К сравнению</button><button class="outline-button" data-action="party-add" data-id="${r.id}">+ В план вечеринки</button><button class="outline-button" data-action="party-go" data-id="${r.id}">В список покупок →</button></div><label class="recipe-servings-label">Количество порций<input type="number" id="recipe-servings" min="1" max="100" value="${recipePortions}"></label><h2>Ингредиенты</h2><ul class="ingredients">${r.parts.map(p=>`<li>${esc(ingredients[p.id].name)} — <span data-amount="${p.amount}">${number(p.amount*recipePortions)}</span> ${esc(ingredients[p.id].unit)}</li>`).join('')}</ul><p class="hint">Украшение: ${esc(r.garnish)}</p><p class="hint">Инструменты: ${esc(r.tools)}</p><p class="hint">${esc(data.abvNote)}</p></div></div><section class="glass-panel substitutions"><h2>Замены ингредиентов</h2><p class="hint">Только варианты для этого рецепта. Замена меняет классический состав.</p>${recipe(r.id).substitutions.length?recipe(r.id).substitutions.map(s=>`<div class="substitution-row"><label>${esc(ingredients[s.fromId].name)}<select data-substitute="${s.fromId}"><option value="">Оригинал</option><option value="${s.toId}"${selectedSubs[s.fromId]===s.toId?' selected':''}>${esc(ingredients[s.toId].name)} · ${s.ratio}:1</option></select></label><p>${esc(s.note)}</p></div>`).join(''):'<p>Для этого рецепта проверенных замен пока не добавлено.</p>'}<p class="hint">Варианты справочные. Перед публикацией пользовательского рецепта требуется редакционная проверка.</p><p class="hint">В план и сравнение добавляется исходный рецепт, без выбранных здесь замен.</p></section><section class="method"><p class="eyebrow">ШАГ ЗА ШАГОМ</p><h2>Как приготовить</h2><p class="cooking-progress" role="status">Готово: 0 из ${r.steps.length} шагов</p><ol>${r.steps.map((s,i)=>`<li><label><input type="checkbox" class="recipe-step" aria-label="Шаг ${i+1} выполнен"><span>${esc(s)}${r.stepPhotos?.[i]?`<img class="step-photo" src="${apiBase}/media/${esc(r.stepPhotos[i])}" alt="Шаг ${i+1}" loading="lazy">`:""}</span></label></li>`).join('')}</ol>${!r.stepPhotos||r.stepPhotos.length<r.steps.length?`<p class="hint">Фотографии отдельных этапов пока не опубликованы полностью. Не подменяем их фотографиями готового напитка.</p>`:""}</section><section class="glass-panel review-section"><h2>Рейтинг и отзывы</h2><div class="reviews-content"><p>Загружаем отзывы…</p></div></section><section class="page-section"><h2>Похожие коктейли</h2>${grid(data.recipes.filter(x=>x.id!==r.id&&x.alcoholic===r.alcoholic).slice(0,3))}</section>`;loadReviews(root,r.id)}
async function loadReviews(root,id){const container=root.querySelector('.reviews-content');if(!server){container.innerHTML='<p>Общие рейтинги и отзывы будут доступны после подключения сервера. Оценки не выдумываем.</p><a class="text-link" href="account.html">О личном кабинете →</a>';return}try{const result=await api('/reviews?recipe='+encodeURIComponent(id));container.innerHTML=`<p>${result.count?`★ ${number(result.average)} · опубликованных отзывов: ${result.count}`:'Опубликованных отзывов пока нет.'}</p><label>Сортировка<select id="review-sort"><option value="date">Сначала новые</option><option value="rating">По оценке</option></select></label><div class="reviews-list"></div>${user?`<form id="review-form"><label>Оценка<select name="rating" required>${[5,4,3,2,1].map(n=>`<option value="${n}">${n} / 5</option>`).join('')}</select></label><label>Ваш отзыв<textarea name="text" required maxlength="2000"></textarea></label><label>Фото напитка (JPEG/PNG/WebP, до 3 МБ)<input name="image" type="file" accept="image/jpeg,image/png,image/webp"></label><button class="outline-button">Отправить на модерацию</button><p class="hint">Рейтинг учитывает только опубликованные отзывы.</p></form>`:'<a class="text-link" href="account.html">Войдите, чтобы оставить отзыв →</a>'}`;function list(){const items=[...result.reviews].sort((a,b)=>container.querySelector('#review-sort').value==='rating'?b.rating-a.rating:b.created_at-a.created_at);container.querySelector('.reviews-list').innerHTML=items.map(r=>`<article class="user-review"><h3>${esc(r.author)} · ${r.rating}/5</h3><p>${esc(r.text)}</p>${r.image?`<img class="review-photo" src="${apiBase}/media/${esc(r.image)}" alt="Фото автора отзыва" loading="lazy">`:''}<p class="hint">${r.status==='pending'?'На модерации · видно только вам':'Опубликован'}</p>${r.can_edit?`<button class="tool-button" data-action="review-edit" data-id="${r.id}" data-text="${esc(r.text)}" data-rating="${r.rating}">Редактировать</button><button class="tool-button" data-action="review-delete" data-id="${r.id}">Удалить</button>`:''}</article>`).join('')}list();container.querySelector('#review-sort').addEventListener('change',list);container.querySelector('#review-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);let image;const file=f.get('image');if(file?.size){if(file.size>3*1024*1024){setNotice('Фото должно быть не больше 3 МБ.');return}image=await fileData(file)}try{await api('/reviews','POST',{recipe_id:id,rating:Number(f.get('rating')),text:f.get('text'),image});setNotice('Отзыв отправлен на модерацию.');await loadReviews(root,id)}catch(err){setNotice(err.message)}})}catch(err){container.textContent=err.message}}
function fileData(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}
const encyclopedia=[
{id:'vodka',name:'Водка',summary:'Крепкий дистиллированный напиток с относительно нейтральным вкусовым профилем.',production:'Производится из пищевого спирта и воды. В качестве сырья для спирта используют зерно, картофель и другие сельскохозяйственные продукты.',types:'Классическая, ароматизированная, настоянная на растительном сырье.',profile:'Часто около 40%, но зависит от продукта. От нейтрального до зернового или пряного вкуса.',brands:'Absolut — Швеция; Finlandia — Финляндия; Belvedere — Польша.',fact:'Нейтральность делает водку распространённой основой фруктовых и ягодных коктейлей.',base:'Водка'},
{id:'rum',name:'Ром',summary:'Напиток из продуктов переработки сахарного тростника.',production:'Сбраживают мелассу или сок сахарного тростника, затем перегоняют. Выдержка и фильтрация зависят от стиля.',types:'Белый, золотой, тёмный, выдержанный; отдельная традиция — ром из сока тростника.',profile:'Часто 37,5–50%; встречаются более крепкие варианты. Тростниковые, фруктовые, ванильные и пряные оттенки.',brands:'Bacardí — происхождение Куба; Appleton Estate — Ямайка; Mount Gay — Барбадос.',fact:'Цвет не всегда надёжно определяет возраст: на него влияют фильтрация, бочка и технологические решения.',base:'Ром'},
{id:'gin',name:'Джин',summary:'Крепкий напиток с обязательным характером можжевельника.',production:'Спирт ароматизируют можжевельником и другими растительными компонентами; способы дистилляции и настаивания различаются.',types:'London Dry, дистиллированный джин, Old Tom и современные стили.',profile:'Часто 37,5–47%; можжевельник, цитрус, кориандр и другие ботанические оттенки.',brands:'Beefeater — Англия; Tanqueray — происхождение Англия; Hendrick’s — Шотландия.',fact:'London Dry обозначает требования к производству, а не обязательное производство в Лондоне.',base:'Джин'},
{id:'whisky',name:'Виски',summary:'Зерновой дистиллят, обычно выдержанный в деревянной бочке.',production:'Зерно сбраживают, перегоняют и выдерживают. Правила сырья, бочек и срока зависят от страны и категории.',types:'Солодовый, зерновой, купажированный, бурбон, ржаной.',profile:'Обычно от 40%; бочковые версии могут быть заметно крепче. Зерно, ваниль, дуб, фрукты, иногда дым.',brands:'Glenfiddich — Шотландия; Jameson — Ирландия; Maker’s Mark — США.',fact:'Виски и whiskey — варианты написания; традиция зависит от региона и бренда.',base:'Виски'},
{id:'tequila',name:'Текила',summary:'Мексиканский напиток из голубой агавы в установленных регионах производства.',production:'Агаву готовят, извлекают сахара, сбраживают и перегоняют. Часть стилей выдерживают в бочках.',types:'Blanco, reposado, añejo, extra añejo; есть и другие регламентированные категории.',profile:'Часто 35–40%, встречаются иные значения. Агава, цитрус, перец; после выдержки — ваниль и древесина.',brands:'José Cuervo — Мексика; Patrón — Мексика; Don Julio — Мексика.',fact:'Голубая агава — суккулент, а не кактус.',base:'Текила'},
{id:'brandy',name:'Коньяк и бренди',summary:'Бренди — семейство дистиллятов из вина и фруктового сырья. Коньяк — защищённая региональная категория.',production:'Вино или фруктовую основу перегоняют; для многих стилей важна выдержка в дубе.',types:'Коньяк, арманьяк, виноградный и фруктовый бренди.',profile:'Часто около 40%. Фрукты, сухофрукты, специи и древесные оттенки.',brands:'Hennessy — Франция; Rémy Martin — Франция; Torres — Испания.',fact:'Не любой бренди можно называть коньяком: наименование связано с регионом и правилами производства.',base:'Бренди'},
{id:'wine',name:'Вино',summary:'Напиток, полученный алкогольным брожением виноградного сока.',production:'На стиль влияют сорт, климат, контакт с кожицей, брожение и выдержка.',types:'Белое, розовое, красное, игристое; сухое, полусухое, полусладкое и сладкое.',profile:'Многие тихие вина 9–15%; креплёные — выше. Вкус зависит от сорта, кислотности, танинов и сахара.',brands:'Antinori — Италия; Torres — Испания; Freixenet — Испания.',fact:'В игристом вине пузырьки могут образовываться при вторичном брожении; методы производства различаются.',base:'Игристое вино'},
{id:'beer',name:'Пиво',summary:'Ферментированный напиток, обычно на основе воды, солода, хмеля и дрожжей.',production:'Готовят сусло из зернового сырья, кипятят с хмелем, сбраживают и выдерживают.',types:'Лагер, эль, стаут, портер, пшеничное, кислые стили.',profile:'Часто 3–8%, но диапазон значительно шире. Солодовые, хмелевые и дрожжевые оттенки.',brands:'Guinness — Ирландия; Weihenstephaner — Германия; Pilsner Urquell — Чехия.',fact:'Горечь и крепость — разные характеристики: более горькое пиво не обязательно крепче.',base:'Пиво'},
{id:'liqueurs',name:'Ликёры',summary:'Сладкие алкогольные напитки с фруктовыми, травяными, кофейными и другими ароматами.',production:'Ароматическую основу получают настаиванием, дистилляцией и другими методами, затем смешивают с сахаром и спиртовой частью.',types:'Цитрусовые, ягодные, травяные, кофейные, сливочные и другие.',profile:'Крепость очень разная, часто 15–40%. Содержание сахара и насыщенность также различаются.',brands:'Cointreau — Франция; Kahlúa — Мексика; Baileys — Ирландия.',fact:'При замене ликёра учитывают не только аромат, но и сахар и крепость.',base:'Ликёры'},
{id:'absinthe',name:'Абсент',summary:'Крепкий анисовый напиток с полынью и другими растительными компонентами.',production:'Растительное сырьё настаивают на спирте; традиционные стили также дистиллируют. Окрашивание может быть натуральным.',types:'Зелёный, бесцветный и другие варианты, различающиеся рецептурой.',profile:'Нередко 45–74%; анис, полынь и фенхель. Сверяйте конкретную этикетку.',brands:'Pernod Absinthe — Франция; La Fée — Франция; Kübler — Швейцария.',fact:'Помутнение при добавлении воды связано с эфирными маслами. Поджигание для подачи не требуется.',base:'Абсент'},
{id:'other',name:'Другие напитки',summary:'Вермуты, аперитивы, писко, кашаса, саке и многие региональные традиции.',production:'Это разные категории с собственным сырьём и правилами; их нельзя объединить одним способом производства.',types:'Вермут, горький аперитив, писко, кашаса, саке.',profile:'Крепость и вкус зависят от категории: от винных до крепких дистиллированных стилей.',brands:'Martini — Италия (вермут); Campari — Италия (аперитив); Leblon — Бразилия (кашаса).',fact:'Вермут — ароматизированное креплёное вино, поэтому после открытия его обычно хранят охлаждённым.',base:'Джин'}
];
function encyclopediaPage(root){const source=data.encyclopedia||encyclopedia;const id=root.dataset.categoryId||new URLSearchParams(location.search).get('category');const item=source.find(x=>x.id===id);if(!item){root.innerHTML='<div class="encyclopedia-grid">'+source.map(x=>`<a class="glass-panel encyclopedia-card" href="${["vodka","rum","gin","whisky","tequila","brandy","wine","beer","liqueurs","absinthe","other"].includes(x.id)?"encyclopedia-"+esc(x.id)+".html":"encyclopedia.html?category="+encodeURIComponent(x.id)}"><h2>${esc(x.name)}</h2><p>${esc(x.summary)}</p><span class="text-link">Открыть раздел →</span></a>`).join('')+'</div>';return}const pictured=data.recipes.find(r=>r.base===item.base&&recipePhotos[r.id]);const cover=pictured?`https://www.thecocktaildb.com/images/media/drink/${recipePhotos[pictured.id]}.jpg`:'https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=max&w=1920&q=85';const caption=pictured?pictured.name+' · фото TheCocktailDB':'Атмосфера коктейльного бара · фото Unsplash';root.innerHTML=`<article class="editorial encyclopedia-article"><figure class="encyclopedia-photo"><img src="${cover}" alt="${esc(caption)}" loading="lazy"><figcaption>${esc(caption)}</figcaption></figure><h2>${esc(item.name)}</h2><p>${esc(item.summary)}</p><h3>Производство</h3><p>${esc(item.production)}</p><h3>Основные виды</h3><p>${esc(item.types)}</p><h3>Характеристики</h3><p>${esc(item.profile)}</p><h3>Примеры производителей</h3><div class="brand-cards">${item.brands.split(';').map(b=>`<div class="brand-card">${esc(b)}</div>`).join('')}</div><h3>Знаете ли вы?</h3><p>${esc(item.fact)}</p><p class="hint">Диапазоны ориентировочные. Точные сведения смотрите на этикетке производителя. Бренды приведены как примеры, без связи с проектом.</p></article><h2>В коктейлях</h2>${grid(data.recipes.filter(r=>r.base===item.base))}<a class="text-link back-link" href="encyclopedia.html">← Вся энциклопедия</a>`}
function localSummary(){return `<div class="account-stats"><a href="favorites.html"><b>${state.favorites.length}</b> Избранных</a><a href="planner.html"><b>${state.plans.length}</b> Планов</a><a href="builder.html?mode=create"><b>${state.custom.length}</b> Своих рецептов</a><a href="builder.html?mode=bar"><b>${Object.values(state.pantry).filter(x=>x>0).length}</b> Ингредиентов дома</a></div>`}
async function account(root){root.innerHTML=toolbar()+localSummary();if(!server){root.innerHTML+=`<div class="glass-panel"><h2>Пока на этом устройстве</h2><p>Локальные инструменты уже работают. Настоящие аккаунты, синхронизация и отзывы требуют серверной версии.</p><p class="hint">На GitHub Pages сервер не запускается. Приложение подготовлено к размещению на вашем сервере; после подключения здесь появятся регистрация и вход.</p><p>Google и Apple не подключены. Пароли в браузере не сохраняются.</p></div><button class="tool-button danger" data-action="local-clear">Удалить локальные данные</button>`;return}if(!user){root.innerHTML+=`<div class="auth-grid"><form class="glass-panel" id="login-form"><h2>Войти</h2><label>Email<input name="email" type="email" autocomplete="email" required></label><label>Пароль<input name="password" type="password" autocomplete="current-password" required minlength="10" maxlength="128"></label><button class="outline-button">Войти</button><p class="auth-message" role="status"></p></form><form class="glass-panel" id="register-form"><h2>Создать аккаунт</h2><label>Имя<input name="name" required maxlength="80" autocomplete="nickname"></label><label>Email<input name="email" type="email" required autocomplete="email"></label><label>Пароль (10–128 символов)<input name="password" type="password" required minlength="10" maxlength="128" autocomplete="new-password"></label><button class="outline-button">Зарегистрироваться</button><p class="auth-message" role="status"></p></form></div><p class="hint">Вход через Google и Apple не подключён.${serverFeatures.passwordReset?'':' Отправка email не настроена: подтверждение почты и восстановление пароля пока недоступны.'}</p>`;for(const id of ['login','register'])root.querySelector('#'+id+'-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{const result=await api('/'+id,'POST',Object.fromEntries(f));user=result.user;await updateAccountLink();setNotice('Вы вошли в аккаунт.');account(root)}catch(err){e.target.querySelector('.auth-message').textContent=err.message}});return}root.innerHTML+=`<div class="glass-panel"><h2>${esc(user.name)}</h2><p>${esc(user.email)}</p><p class="hint">${user.role==='admin'?'Администратор':'Пользователь'}</p><button class="outline-button" data-action="cloud-save">Сохранить данные в аккаунте</button> <button class="outline-button" data-action="cloud-load">Загрузить данные из аккаунта</button><p class="hint">Загрузка заменяет локальную коллекцию после подтверждения ниже. Автоматически данные не перезаписываются.</p><div class="confirm-cloud" hidden><p>Заменить данные этого устройства сохранёнными данными аккаунта?</p><button class="tool-button" data-action="cloud-confirm">Да, заменить</button></div>${user.role==='admin'?'<a class="text-link" href="admin.html">Административная панель →</a>':''}<button class="tool-button" data-action="logout">Выйти</button></div><form class="glass-panel" id="avatar-form"><h2>Мой аватар</h2>${user.avatar?`<img class="avatar-photo" src="${apiBase}/media/${esc(user.avatar)}" alt="Ваш аватар">`:""}<label>Фото (до 3 МБ)<input name="image" type="file" accept="image/jpeg,image/png,image/webp" required></label><button class="outline-button">Сохранить аватар</button><p class="auth-message" role="status"></p></form><form class="glass-panel" id="profile-form"><h2>Мой профиль</h2><label>Имя<input name="name" value="${esc(user.name)}" required maxlength="80"></label><label>Email<input name="email" type="email" required value="${esc(user.email)}"></label><label>Текущий пароль для изменения email/пароля<input name="current_password" type="password" autocomplete="current-password"></label><label>Новый пароль (необязательно)<input name="new_password" type="password" minlength="10" maxlength="128" autocomplete="new-password"></label><button class="outline-button">Сохранить профиль</button><p class="auth-message" role="status"></p></form><form class="glass-panel" id="preferences-form"><h2>Мои предпочтения</h2><label>Любимый вкус<select name="taste">${options(unique('taste'),state.preferences.taste)}</select></label><label>Любимая основа<select name="base">${options(unique('base'),state.preferences.base)}</select></label><label>Предпочитаемый ингредиент<select name="ingredient">${options(data.ingredients,state.preferences.ingredient)}</select></label><label>Тип напитка<select name="type">${options(unique("type"),state.preferences.type)}</select></label><label class="checkbox-label"><input name="public_name" type="checkbox"${state.preferences.public_name!==false?' checked':''}> Показывать моё имя в отзывах</label><p class="hint">Email-уведомления пока не подключены; подписки на уведомления здесь не собираются.</p><button class="outline-button">Сохранить предпочтения на устройстве</button></form><div class="glass-panel"><h2>Мои рецепты в сообществе</h2><div class="submitted-recipes">Загружаем…</div></div><div class="glass-panel"><h2>Мои отзывы</h2><div class="my-reviews">Загружаем…</div></div><div class="glass-panel"><h2>Удаление данных</h2><button class="tool-button danger" data-action="local-clear">Удалить локальные данные</button><form id="delete-account"><label>Для удаления аккаунта введите пароль<input type="password" name="password" required autocomplete="current-password"></label><label class="checkbox-label"><input type="checkbox" name="confirm" required> Удалить аккаунт, отзывы и сохранённые данные без восстановления</label><button class="tool-button danger">Удалить аккаунт</button><p class="auth-message" role="status"></p></form></div>`;root.querySelector('#avatar-form').addEventListener('submit',async e=>{e.preventDefault();try{const file=new FormData(e.target).get('image');if(file.size>3*1024*1024)throw Error('Фото должно быть не больше 3 МБ.');await api('/avatar','POST',{image:await fileData(file)});user=(await api('/me')).user;account(root)}catch(err){e.target.querySelector('.auth-message').textContent=err.message}});root.querySelector('#profile-form').addEventListener('submit',async e=>{e.preventDefault();try{const r=await api('/profile','PUT',Object.fromEntries(new FormData(e.target)));user=r.user;account(root)}catch(err){e.target.querySelector('.auth-message').textContent=err.message}});root.querySelector('#preferences-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);state.preferences={taste:f.get('taste'),base:f.get('base'),ingredient:f.get('ingredient'),type:f.get('type'),public_name:f.has('public_name')};persist();setNotice('Предпочтения сохранены. Для синхронизации нажмите «Сохранить данные в аккаунте».')});root.querySelector('#delete-account').addEventListener('submit',async e=>{e.preventDefault();try{await api('/account','DELETE',{password:new FormData(e.target).get('password')});user=null;updateAccountLink();account(root);setNotice('Аккаунт удалён.')}catch(err){e.target.querySelector('.auth-message').textContent=err.message}});try{const submitted=await api('/my-recipes');root.querySelector('.submitted-recipes').innerHTML=submitted.recipes.map(r=>`<p>${esc(r.recipe.name)} · ${{pending:'На проверке',published:'Опубликован',rejected:'Отклонён редактором'}[r.status]||esc(r.status)}</p>`).join('')||'Вы пока не отправляли рецепты сообществу.'}catch(err){root.querySelector('.submitted-recipes').textContent=err.message}try{const reviews=await api('/my-reviews');root.querySelector('.my-reviews').innerHTML=reviews.reviews.map(r=>`<p><a class="text-link" href="${recipeURL(r.recipe_id)}">${esc(recipe(r.recipe_id)?.name||r.recipe_id)}</a> · ${r.rating}/5 · ${r.status==='published'?'Опубликован':'На модерации'}<br>${esc(r.text)}</p>`).join('')||'Вы пока не оставляли отзывов.'}catch(err){root.querySelector('.my-reviews').textContent=err.message}}
async function admin(root){root.innerHTML=toolbar();if(!server||!user||user.role!=='admin'){root.innerHTML+='<div class="glass-panel"><h2>Доступ ограничен</h2><p>Нужен вход в серверную версию с правами администратора. Скрытие этой страницы не заменяет проверку прав: каждый административный запрос проверяется сервером.</p><a class="text-link" href="account.html">Личный кабинет →</a></div>';return}try{const result=await api('/admin/summary');root.innerHTML+=`<div class="glass-panel"><h2>Отзывы на модерации</h2>${result.reviews.map(r=>`<article class="user-review"><h3>${esc(r.author)} · ${esc(r.recipe_id)} · ${r.rating}/5</h3><p>${esc(r.text)}</p>${r.image?`<img class="review-photo" src="${apiBase}/media/${esc(r.image)}" alt="Фото отзыва на модерации">`:''}<button class="tool-button" data-action="admin-review-publish" data-id="${r.id}">Опубликовать</button><button class="tool-button danger" data-action="review-delete" data-id="${r.id}">Удалить</button></article>`).join('')||'<p>Нет ожидающих отзывов.</p>'}</div><div class="glass-panel"><h2>Пользователи</h2>${result.users.map(u=>`<div class="admin-user"><span>${esc(u.name)} · ${esc(u.email)} · ${u.blocked?'заблокирован':esc(u.role)}</span>${u.id!==user.id?`<button class="tool-button" data-action="admin-user-block" data-id="${u.id}" data-blocked="${u.blocked?0:1}">${u.blocked?'Разблокировать':'Заблокировать'}</button><button class="tool-button danger" data-action="admin-user-delete" data-id="${u.id}">Удалить</button>`:''}</div>`).join('')}</div><div class="glass-panel"><h2>Рецепты пользователей</h2>${result.custom.map(r=>`<article class="user-review"><h3>${esc(r.recipe.name)} · ${esc(r.author)}</h3><p>${esc(r.recipe.description)}</p><ul>${r.recipe.parts.map(p=>`<li>${esc(ingredients[p.id]?.name||p.id)} — ${number(p.amount)} ${esc(ingredients[p.id]?.unit||"")}</li>`).join("")}</ul><button class="tool-button" data-action="admin-custom-publish" data-id="${r.id}">Одобрить и добавить в каталог</button><button class="tool-button danger" data-action="admin-custom-reject" data-id="${r.id}">Отклонить</button></article>`).join("")||"<p>Нет рецептов на проверке.</p>"}</div><form class="glass-panel" id="admin-upload"><h2>Загрузить фотографию</h2><p>Фото карточки или шага рецепта. После загрузки добавьте полученный идентификатор в поле photo или stepPhotos нужного рецепта в каталоге ниже. Публикуйте только изображения с правом использования.</p><label>Изображение<input type="file" name="image" accept="image/jpeg,image/png,image/webp" required></label><button class="outline-button">Загрузить фото</button><p class="upload-result" role="status"></p></form><form class="glass-panel" id="admin-content"><h2>Каталог, ингредиенты и замены</h2><p>Редактор структуры каталога. Сервер проверяет идентификаторы, дозировки и ссылки на ингредиенты. Изменения видны в серверной версии. Перед редактированием скачайте резервную копию.</p><a class="text-link" href="${apiBase}/catalog" download="catalog-backup.json">Скачать текущий каталог →</a><label>Данные каталога JSON<textarea name="catalog" class="json-editor" spellcheck="false">${esc(JSON.stringify(data,null,2))}</textarea></label><button class="outline-button">Проверить и сохранить каталог</button><p class="auth-message" role="status"></p><p class="hint">Карточки без фотографии должны использовать схематичную иллюстрацию. Изображения по этапам и фотографии новых коктейлей требуют загрузки и редакционной проверки. Новые рецепты открываются по адресу recipe.html?id=идентификатор.</p></form>`;root.querySelector('#admin-upload').addEventListener('submit',async e=>{e.preventDefault();try{const file=new FormData(e.target).get('image');if(file.size>3*1024*1024)throw Error('Фото должно быть не больше 3 МБ.');const r=await api('/admin/uploads','POST',{image:await fileData(file)});e.target.querySelector('.upload-result').textContent='Идентификатор фото: '+r.id}catch(err){e.target.querySelector('.upload-result').textContent=err.message}});root.querySelector('#admin-content').addEventListener('submit',async e=>{e.preventDefault();try{const next=JSON.parse(new FormData(e.target).get('catalog'));await api('/admin/catalog','PUT',next);data=next;ingredients=C.index(data);state=C.validState(state,data);persist();e.target.querySelector('.auth-message').textContent='Каталог сохранён. Обновите нужную страницу.'}catch(err){e.target.querySelector('.auth-message').textContent=err.message}})}catch(err){root.innerHTML+='<p>'+esc(err.message)+'</p>'}}
async function updateAccountLink(){document.querySelectorAll('.account-link').forEach(el=>el.textContent=user?'Мой кабинет →':'Войти →')}
function updateCounters(){document.querySelectorAll('[data-compare-count]').forEach(el=>el.textContent=state.compare.length?`(${state.compare.length})`:'')}
function render(root){const view=root.dataset.view;updateCounters();if(['catalog','mocktails','occasions'].includes(view))renderCatalog(root,view);else if(view==='popular')root.innerHTML=grid(data.recipes.filter(r=>r.alcoholic).slice(0,3));else if(view==='favorites')root.innerHTML=toolbar()+grid(state.favorites.map(recipe).filter(Boolean));else if(view==='compare')comparePage(root);else if(view==='planner')planner(root);else if(view==='builder')builder(root);else if(view==='recipe')recipePage(root);else if(view==='account')account(root);else if(view==='admin')admin(root);else if(view==='encyclopedia')encyclopediaPage(root)}
function portion(root){const n=Math.max(1,Math.min(100,Number(root.querySelector('#recipe-servings')?.value)||1));return Math.floor(n)}
function updatePortions(root){const n=portion(root);root.querySelector('#recipe-servings').value=n;root.querySelectorAll('[data-amount]').forEach(el=>el.textContent=number(Number(el.dataset.amount)*n))}
function bounded(input,max=100000){const n=Number(input.value);if(!Number.isFinite(n)||n<0||n>max){input.setCustomValidity(`Введите число от 0 до ${max}.`);input.reportValidity();return null}input.setCustomValidity('');return n}
for(const root of roots){root.addEventListener('input',e=>{const el=e.target;if(el.dataset.filter!==undefined){filters[el.dataset.filter]=el.type==='checkbox'?el.checked:el.value;catalogResults(root,root.dataset.view==='builder'?'builder':root.dataset.view)}if(el.id==='recipe-servings'){recipePortions=portion(root);updatePortions(root)};if(el.matches('.custom-ingredient,.custom-amount'))customCalculation(root)});root.addEventListener('change',e=>{const el=e.target;if(el.dataset.pantry){const n=bounded(el);if(n===null)return;state.pantry[el.dataset.pantry]=n;delete state.adjustments[el.dataset.pantry];persist();if(root.dataset.view==='planner')planner(root);else barResults(root)}if(el.dataset.party){const n=bounded(el,100);if(n===null||n<1||!Number.isInteger(n)){setNotice('Количество порций — целое число от 1 до 100.');return}state.party[el.dataset.party]=n;state.adjustments={};persist();planner(root)}if(el.dataset.adjustment){const n=bounded(el);if(n===null)return;state.adjustments[el.dataset.adjustment]=n;persist()}if(el.dataset.bought){state.bought[el.dataset.bought]=el.checked;persist();el.closest('tr').classList.toggle('purchased',el.checked)}if(el.dataset.substitute!==undefined){if(el.value)selectedSubs[el.dataset.substitute]=el.value;else delete selectedSubs[el.dataset.substitute];recipePage(root)}if(el.classList.contains('recipe-step')){el.closest('li').classList.toggle('step-done',el.checked);root.querySelector('.cooking-progress').textContent=`Готово: ${root.querySelectorAll('.recipe-step:checked').length} из ${root.querySelectorAll('.recipe-step').length} шагов`}});root.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(button)action(root,button).catch(err=>setNotice(err.message))})}
async function action(root,button){const id=button.dataset.id,act=button.dataset.action;
if(act==='favorite'){const exists=state.favorites.includes(id);state.favorites=exists?state.favorites.filter(x=>x!==id):[...state.favorites,id];persist();setNotice(exists?'Убрано из избранного.':'Сохранено в избранное на этом устройстве.');if(root.dataset.view==='recipe'){button.textContent=exists?'♡ В избранное':'♥ Сохранено';button.setAttribute('aria-pressed',String(!exists))}else render(root)}
else if(act==='compare'){if(state.compare.includes(id))state.compare=state.compare.filter(x=>x!==id);else{if(state.compare.length>=4){setNotice('В сравнении уже четыре коктейля. Уберите один на странице сравнения.');return}state.compare.push(id)}persist();setNotice('Список сравнения обновлён.');if(root.dataset.view!=='recipe')render(root);else button.textContent=state.compare.includes(id)?'✓ В сравнении':'⚖ К сравнению';updateCounters()}
else if(['party-add','party-go'].includes(act)){const guests=Number(root.querySelector('#guest-count')?.value)||1,n=root.dataset.view==='recipe'?portion(root):Math.max(1,Math.min(100,Math.floor(guests)));state.party[id]=Math.min(100,(state.party[id]||0)+n);state.adjustments={};persist();setNotice('Рецепт добавлен в план. Состав — исходный, без замен.');if(act==='party-go')location.href='planner.html'}
else if(act==='occasion'){filters.occasion=id;render(root)}
else if(act==='reset-filters'){filters={};render(root)}
else if(act==='compare-to-party'){state.compare.forEach(id=>state.party[id]=state.party[id]||1);state.adjustments={};persist();location.href='planner.html'}
else if(act==='party-selected'){const selected=root.querySelector('#party-recipe').value;if(!selected){setNotice('Выберите рецепт.');return}state.party[selected]=Math.min(100,(state.party[selected]||0)+1);state.adjustments={};persist();planner(root)}
else if(act==='shared-accept'){state.party={...pendingShared};state.adjustments={};state.bought={};pendingShared=null;persist();history.replaceState(null,'',location.pathname);setNotice('Открыт план из ссылки. Домашние запасы не изменены.');planner(root)}
else if(act==='party-remove'){delete state.party[id];state.adjustments={};persist();planner(root)}
else if(act==='shopping-reset'){state.adjustments={};persist();planner(root)}
else if(act==='plan-load'){const plan=state.plans[Number(id)];state.party={...plan.party};state.pantry={...(plan.pantry||state.pantry)};state.adjustments={...(plan.adjustments||{})};state.bought={...(plan.bought||{})};persist();planner(root)}
else if(act==='plan-delete'){state.plans.splice(Number(id),1);persist();planner(root)}
else if(act==='copy-shopping'){const rows=C.shopping(state.party,data.recipes,ingredients,state.pantry);const text='Список покупок — Drunken Guide\n'+rows.map(i=>`${state.bought[i.id]?'✓':'□'} ${i.name}: ${number(state.adjustments[i.id]??i.missing)} ${i.unit}`).join('\n');await copy(text,root)}
else if(act==='share-party'){const payload=btoa(unescape(encodeURIComponent(JSON.stringify(state.party)))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');const url=new URL('planner.html',location.href);url.searchParams.set('plan',payload);await copy(url.href,root)}
else if(act==='custom-add')addCustomPart(root);
else if(act==='custom-remove'){button.closest('.custom-part').remove();customCalculation(root)}
else if(act==='custom-submit'){await api('/custom-recipes','POST',{recipe:state.custom[Number(id)]});setNotice('Рецепт отправлен на редакционную модерацию.')}
else if(act==='custom-delete'){state.custom.splice(Number(id),1);persist();root.querySelector('.custom-saved')?root.querySelector('.custom-saved').innerHTML=customList():render(root)}
else if(act==='logout'){await api('/logout','POST',{});user=null;updateAccountLink();account(root)}
else if(act==='cloud-save'){await api('/state','PUT',{state});setNotice('Данные сохранены в аккаунте на сервере.')}
else if(act==='cloud-load')root.querySelector('.confirm-cloud').hidden=false;
else if(act==='cloud-confirm'){const result=await api('/state');state=C.validState(result.state,data);persist();setNotice('Данные аккаунта загружены на устройство.');account(root)}
else if(act==='local-clear'){root.innerHTML=toolbar()+'<div class="glass-panel"><h2>Удалить данные этого браузера?</h2><p>Избранное, домашний бар, планы и свои рецепты будут удалены с устройства. Серверные данные аккаунта останутся.</p><button class="tool-button danger" data-action="local-clear-confirm">Да, удалить локальные данные</button><a class="text-link" href="account.html">Отмена</a></div>'}
else if(act==='local-clear-confirm'){state=C.validState({},data);persist();setNotice('Локальные данные удалены.');account(root)}
else if(act==='review-delete'){await api('/reviews/'+id,'DELETE');if(root.dataset.view==='admin')admin(root);else loadReviews(root,root.dataset.recipeId)}
else if(act==='review-edit'){const box=button.closest('.user-review');box.innerHTML=`<form class="review-edit-form"><label>Оценка<select name="rating">${[5,4,3,2,1].map(n=>`<option value="${n}"${n===Number(button.dataset.rating)?' selected':''}>${n}</option>`).join('')}</select></label><label>Текст<textarea name="text" required maxlength="2000">${esc(button.dataset.text)}</textarea></label><button class="outline-button">Сохранить и отправить на модерацию</button></form>`;box.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();try{const f=new FormData(e.target);await api('/reviews/'+id,'PUT',{rating:Number(f.get('rating')),text:f.get('text')});loadReviews(root,root.dataset.recipeId)}catch(err){setNotice(err.message)}})}
else if(act==='admin-custom-publish'||act==='admin-custom-reject'){await api('/admin/custom-recipes/'+id,'PUT',{status:act==='admin-custom-publish'?'published':'rejected'});const updated=await api('/catalog');data=updated;ingredients=C.index(data);admin(root)}
else if(act==='admin-review-publish'){await api('/admin/reviews/'+id,'PUT',{status:'published'});admin(root)}
else if(act==='admin-user-block'){await api('/admin/users/'+id,'PUT',{blocked:button.dataset.blocked==='1'});admin(root)}
else if(act==='admin-user-delete'){button.closest('.admin-user').innerHTML=`<p>Удалить пользователя и все его отзывы?</p><button class="tool-button danger" data-action="admin-user-delete-confirm" data-id="${id}">Да, удалить</button><a class="text-link" href="admin.html">Отмена</a>`}
else if(act==='admin-user-delete-confirm'){await api('/admin/users/'+id,'DELETE');admin(root)}
}
async function copy(text,root){try{await navigator.clipboard.writeText(text);setNotice('Скопировано. Можно отправить ссылку или список.')}catch{const box=root.querySelector('.share-result');box.textContent='Скопируйте текст вручную:';const area=document.createElement('textarea');area.readOnly=true;area.value=text;box.append(area);area.select()}}
try{const response=await fetch('content/platform-data.json?v=3');if(!response.ok)throw Error('Не удалось загрузить каталог.');data=await response.json();ingredients=C.index(data);if(apiBase){try{const status=await api('/status');server=true;serverFeatures=status;const remote=await api('/catalog');data=remote;ingredients=C.index(data);ratings=(await api('/ratings')).ratings;try{user=(await api('/me')).user}catch{}}catch(err){notice='Сервер недоступен. Локальные инструменты продолжают работать.'}}state=load();if(mode==='preferences')filters={taste:state.preferences.taste||'',base:state.preferences.base||'',ingredient:state.preferences.ingredient||'',type:state.preferences.type||''};const params=new URLSearchParams(location.search);if(params.has('occasion')&&data.occasions.some(o=>o.id===params.get('occasion')))filters.occasion=params.get('occasion');if(params.has('plan')){try{let value=params.get('plan');if(value.length>20000)throw Error('Слишком большая ссылка');const shared=JSON.parse(decodeURIComponent(escape(atob(value.replace(/-/g,'+').replace(/_/g,'/')))));pendingShared=C.validState({party:shared},data).party;notice='Получен план из ссылки. Нажмите «Открыть этот план», чтобы заменить текущий.'}catch{notice='Не удалось прочитать план из ссылки.'}}const generic=roots.find(r=>r.dataset.view==='recipe'&&!r.dataset.recipeId);if(generic)generic.dataset.recipeId=params.get('id')||'';await updateAccountLink();roots.forEach(render)}catch(err){roots.forEach(root=>{root.innerHTML='<p class="error-state">'+esc(err.message)+'</p><a href="index.html" class="text-link">Вернуться на главную</a>'})}
})();
